62	/// Stable, process-unique identifier for a `BlockManager`'s underlying
63	/// `BlockStore`.
64	///
65	/// Generated by an atomic counter at `BlockStore` construction; never
66	/// reused. Two [`LifecyclePinRef`]s with the same `ManagerId` come from
67	/// the same physical pool; together with [`BlockId`] this disambiguates
68	/// a slot's logical address after policy-type erasure (downstream callers
69	/// that hold `Arc<dyn LifecyclePin>` lose the manager type parameter but
70	/// keep the runtime address).
71	///
72	/// The reserved value [`ManagerId::NULL`] is never assigned to a real
73	/// store — callers may use it as a null/test sentinel.
74	#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Encode, Decode, Serialize, Deserialize)]
75	pub struct ManagerId(pub u64);
76	
77	impl ManagerId {
78	    /// Sentinel never assigned to a real `BlockStore`.
79	    pub const NULL: Self = Self(0);
80	
81	    /// Allocate the next process-unique `ManagerId`.  Atomic counter,
82	    /// `Relaxed` ordering — uniqueness is guaranteed by `fetch_add`,
83	    /// happens-before is not needed for an opaque scalar id.
84	    pub(crate) fn next() -> Self {
85	        static NEXT: AtomicU64 = AtomicU64::new(1);
86	        Self(NEXT.fetch_add(1, Ordering::Relaxed))
87	    }
88	}
